contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount, address adr) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        require(adr != address(0));

        uint256 preBalance = address(c).balance;
        require(amount >= preBalance);

        c.multiplicate{value: amount}(adr); if (__ESBMC_reverted()) return;

        uint256 postBalance = address(c).balance;
        assert(postBalance >= preBalance + amount - (preBalance + amount));
    }

    receive() external payable {}
}

